import{_ as a,o as c,c as o,a5 as i}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Task — G4 Media Package / Campaign: View + Approve (Mobile)","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/features/g4-package-campaign/task.md","filePath":"mobile/features/g4-package-campaign/task.md"}'),n={name:"mobile/features/g4-package-campaign/task.md"};function t(r,e,d,l,p,s){return c(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="task-—-g4-media-package-campaign-view-approve-mobile" tabindex="-1">Task — G4 Media Package / Campaign: View + Approve (Mobile) <a class="header-anchor" href="#task-—-g4-media-package-campaign-view-approve-mobile" aria-label="Permalink to &quot;Task — G4 Media Package / Campaign: View + Approve (Mobile)&quot;">​</a></h1><p>&gt; <a href="./spec.html">spec.md</a></p><h2 id="media-package-screens" tabindex="-1">Media Package screens <a class="header-anchor" href="#media-package-screens" aria-label="Permalink to &quot;Media Package screens&quot;">​</a></h2><ul><li>[ ] Package List theo Workspace — <code>GET /api/v1/workspaces/{workspaceId}/media-packages</code>.</li><li>[ ] Package Detail — <code>GET /api/v1/workspaces/{workspaceId}/media-package</code>, hiển thị <code>negotiationStatus</code>, <code>finalTerms</code>, <code>approvedByAgencyAt</code>/<code>approvedByClientAt</code>.</li><li>[ ] Nút Approve Package — ẩn/hiện theo <code>approvedBy{Side}At == null</code>; <strong>đọc <code>ApproveMediaPackageRequest</code> DTO thật trước khi code</strong> (mục 8 câu 2, chưa xác nhận có <code>expectedVersion</code> hay không).</li></ul><h2 id="media-campaign-screens" tabindex="-1">Media Campaign screens <a class="header-anchor" href="#media-campaign-screens" aria-label="Permalink to &quot;Media Campaign screens&quot;">​</a></h2><ul><li>[ ] Campaign List theo Workspace — <code>GET /api/v1/workspaces/{workspaceId}/campaigns</code> (<strong>dùng <code>WorkspaceCampaignController</code>, KHÔNG dùng <code>MediaCampaignController</code></strong> — xem mục 8 câu 1).</li><li>[ ] Campaign Detail — <code>GET .../campaigns/{campaignId}</code>, các section: Strategy, Brand Guideline, Timeline (parse jsonb), Deliverables (<code>deliverablePlan</code>+<code>allocations</code>+<code>allocationPeriod</code>), Work Items.</li><li>[ ] Nút Approve Campaign — role-gated: OWNER/MANAGER thấy &quot;Agency duyệt&quot; nếu <code>approvedByAgencyAt==null</code>, CLIENT thấy &quot;Client duyệt&quot; nếu <code>approvedByClientAt==null</code>; ẩn nút + hiện &quot;Đã duyệt lúc ...&quot; nếu phía mình đã duyệt.</li><li>[ ] Mutation approve — <code>POST .../approve</code> body <code>{ expectedVersion: campaign.contentVersion }</code> (đọc tại thời điểm bấm nút, <strong>không dùng <code>rowVersion</code></strong>).</li></ul><h2 id="error-handling-approve" tabindex="-1">Error handling approve <a class="header-anchor" href="#error-handling-approve" aria-label="Permalink to &quot;Error handling approve&quot;">​</a></h2><ul><li>[ ] <code>onError</code> HTTP 409 <code>CAMPAIGN_VERSION_CONFLICT</code> — refetch campaign detail, hiện lại UI với <code>contentVersion</code>/<code>approvedBy*At</code> mới nhất, yêu cầu user bấm Approve lại (không tự động retry).</li><li>[ ] Disable nút khi mutation pending (UX, server đã idempotent theo phía nên không bắt buộc nhưng nên làm).</li><li>[ ] <code>onSuccess</code> — <code>invalidateQueries([&#39;campaign&#39;, workspaceId, campaignId])</code> + <code>invalidateQueries([&#39;campaigns&#39;, workspaceId])</code>.</li></ul><h2 id="business-rules-can-enforce-o-client" tabindex="-1">Business rules cần enforce ở client <a class="header-anchor" href="#business-rules-can-enforce-o-client" aria-label="Permalink to &quot;Business rules cần enforce ở client&quot;">​</a></h2><ul><li>[ ] Dual approval không theo thứ tự — Agency/Client approve độc lập, status giữ <code>DRAFT</code> tới khi đủ cả 2.</li><li>[ ] <code>CampaignStatus</code> chỉ 4 giá trị: <code>DRAFT, APPROVED, IN_PROGRESS, COMPLETED</code> — UI không hiển thị trạng thái &quot;chờ duyệt 1 phía&quot; riêng, vẫn là DRAFT.</li><li>[ ] Campaign ở <code>IN_PROGRESS</code>/<code>COMPLETED</code> không hiện nút Approve (server trả <code>CAMPAIGN_IMMUTABLE</code> nếu cố gọi).</li><li>[ ] Approve KHÔNG tự động đẩy Task — deploy là hành động riêng, không thuộc G4, không hiển thị gộp 2 bước làm 1.</li></ul><h2 id="chua-lam-out-of-scope-g4-xem-spec-muc-7" tabindex="-1">Chưa làm / out of scope G4 (xem spec mục 7) <a class="header-anchor" href="#chua-lam-out-of-scope-g4-xem-spec-muc-7" aria-label="Permalink to &quot;Chưa làm / out of scope G4 (xem spec mục 7)&quot;">​</a></h2><ul><li>[ ] Không làm: tạo Campaign mới, sửa Campaign draft, gửi feedback Campaign, deploy Campaign, complete/cancel Campaign, request/negotiate Package, tạo custom Package.</li></ul><h2 id="rui-ro-can-chot-truoc-khi-code-xem-spec-muc-8" tabindex="-1">Rủi ro cần chốt trước khi code (xem spec mục 8) <a class="header-anchor" href="#rui-ro-can-chot-truoc-khi-code-xem-spec-muc-8" aria-label="Permalink to &quot;Rủi ro cần chốt trước khi code (xem spec mục 8)&quot;">​</a></h2><ol><li>2 controller Campaign trùng route (<code>/media-campaigns/...</code> vs <code>/workspaces/{id}/campaigns/...</code>) — xác nhận với backend route nào chính thức, tránh tích hợp sai route cũ.</li><li><code>ApproveMediaPackageRequest</code> DTO chưa đọc field chi tiết — đọc trước khi code approve Package.</li><li>BA mô tả &quot;approve tự đẩy backlog&quot; khác code (approve/deploy tách riêng) — cần BA/PO xác nhận chủ định.</li><li><code>PackageDeliverable</code>/<code>CampaignWorkItem</code>/<code>DeliverableAllocation</code> DTO con chưa đọc chi tiết — đọc trước khi thiết kế UI render từng field.</li><li>Push notification khi phía kia approve — chưa cover trong G4, để domain notification sau xử lý nếu cần real-time alert.</li></ol>',14)])])}const m=a(n,[["render",t]]);export{g as __pageData,m as default};
